const user = $json;
const dias = user.dias_inativo || 0;
const nome = String(user.nome || 'amigo(a)').replace(/[,.!]+$/g, '').trim() || 'amigo(a)';
const objetivo = user.objetivo || 'manter forma';
const ultimoTreinoBruto = user.ultimo_treino || 'nenhum recente';
const ultimoTreino = String(ultimoTreinoBruto).replace(/\s+/g, ' ').slice(0, 180);
const treinosMes = user.treinos_mes || 0;

// Seleciona tom baseado no tempo de inatividade
let tom;
if (dias <= 3) {
  tom = 'lembrete leve e amigavel';
} else if (dias <= 7) {
  tom = 'motivacional com senso de urgencia gentil';
} else {
  tom = 'empatico e acolhedor, sem julgamento, incentivando retomada';
}

const prompt = `Gere uma mensagem de reengajamento para:
- Nome: ${nome}
- Objetivo: ${objetivo}
- Dias sem interacao: ${dias}
- Ultimo treino: ${ultimoTreino}
- Treinos no mes: ${treinosMes}
- Tom desejado: ${tom}

REGRAS:
- Maximo 4 linhas
- Use 1-2 emojis
- Inclua uma pepita de sabedoria sobre disciplina/saude
- Termine com um CTA claro: sugira /peso, /treino ou /progresso
- Portugues do Brasil
- NUNCA julgue ou critique a ausencia`;

return {
  ...user,
  nome,
  ultimo_treino_resumido: ultimoTreino,
  prompt_nudge: prompt,
  tom: tom
};

