const u = $json;

function cleanName(value) {
  return String(value || 'amigo(a)')
    .replace(/[,.!]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim() || 'amigo(a)';
}

function goalLabel(value) {
  const map = {
    EMAGRECER: 'emagrecer',
    GANHAR_MUSCULO: 'ganhar massa muscular',
    MELHORAR_CONDICIONAMENTO: 'melhorar condicionamento',
    CORRER_5K_10K: 'correr 5km/10km',
    SAUDE_BEM_ESTAR: 'saude e bem-estar',
    GANHAR_FORCA: 'ganhar forca'
  };
  return map[value] || String(value || 'manter forma').toLowerCase().replaceAll('_', ' ');
}

function groupLabel(value) {
  const map = {
    PEITO: 'peito',
    COSTAS: 'costas',
    PERNAS: 'pernas',
    OMBRO: 'ombros',
    BRACOS: 'bracos',
    ABDOMEN: 'abdomen',
    FULLBODY: 'full body',
    CARDIO: 'cardio',
    CORRIDA: 'corrida',
    OUTRO: 'variado'
  };
  return map[value] || String(value || 'variado').toLowerCase().replaceAll('_', ' ');
}

function decimalPt(value) {
  return Number(value).toFixed(1).replace('.', ',');
}

const nome = cleanName(u.nome);
const objetivo = goalLabel(u.objetivo);
const treinos = Number(u.treinos_semana || 0);
const minutos = Number(u.minutos_semana || 0);
const grupoTop = groupLabel(u.grupo_top);
const meta = Number(u.frequencia_treino_estimada || 0);
const pesoInicio = u.peso_inicio_semana;
const pesoFim = u.peso_fim_semana;
const totalHistorico = Number(u.total_treinos_historico || 0);

let pesoDiff = 'Sem registros de peso essa semana';
if (pesoInicio && pesoFim) {
  const diff = Number(pesoFim) - Number(pesoInicio);
  const sinal = diff >= 0 ? '+' : '';
  pesoDiff = `Peso: ${decimalPt(pesoInicio)}kg para ${decimalPt(pesoFim)}kg (${sinal}${decimalPt(diff)}kg)`;
}

let metaMsg = 'Meta semanal nao informada';
if (meta > 0) {
  const pct = Math.round((treinos / meta) * 100);
  metaMsg = `Meta semanal: ${treinos}/${meta} treinos (${pct}% de cumprimento)`;
}

let streakMsg = '';
if (treinos >= meta && meta > 0) {
  streakMsg = 'Meta atingida';
} else if (treinos >= 3) {
  streakMsg = 'Semana produtiva';
}

const prompt = `Gere um resumo semanal motivacional para:
- Nome limpo: ${nome}
- Objetivo: ${objetivo}
- Treinos na semana: ${treinos} (${minutos} minutos total)
- ${metaMsg}
- Grupo mais treinado: ${grupoTop}
- ${pesoDiff}
- Total de treinos no historico: ${totalHistorico}
- Status: ${streakMsg}

REGRAS OBRIGATORIAS:
- Maximo 8 linhas.
- Comece exatamente com: 📊 Resumo semanal, ${nome}!
- Nao coloque virgula entre o nome e o ponto de exclamacao.
- Use somente portugues do Brasil. Nao use palavras ou letras de outros idiomas/alfabetos.
- Nao use Markdown: nao use **, __, titulos ou listas com marcacao.
- Use emojis com moderacao (3 a 5 no total).
- Destaque conquistas primeiro.
- Sugira melhoria gentilmente.
- Inclua um ensinamento sobre consistencia.
- Termine exatamente com: Boa semana! Use /treino para um novo treino ou /progresso para ver graficos`;

return {
  ...u,
  nome,
  objetivo_label: objetivo,
  grupo_top_label: grupoTop,
  peso_diff_label: pesoDiff,
  prompt_semanal: prompt
};

