const u = $json;
const milestones = [];
const totalTreinos = u.total_treinos || 0;
const pesoInicial = u.peso_primeiro;
const pesoAtual = u.peso_atual;
const diasTreinoSemana = u.dias_treino_semana || 0;

// Milestone de treinos
const treinoMilestones = [10, 25, 50, 75, 100, 150, 200, 500];
for (const m of treinoMilestones) {
  if (totalTreinos === m) {
    milestones.push({
      tipo: 'treino',
      valor: m,
      key: `milestone:treino:${u.id}:${m}`,
      descricao: `${m}º treino registrado!`
    });
  }
}

// Milestone de peso perdido
if (pesoInicial && pesoAtual) {
  const perdido = pesoInicial - pesoAtual;
  const pesoMilestones = [3, 5, 10, 15, 20];
  for (const m of pesoMilestones) {
    if (perdido >= m && perdido < m + 1) {
      milestones.push({
        tipo: 'peso',
        valor: m,
        key: `milestone:peso:${u.id}:${m}`,
        descricao: `${m}kg perdidos desde o início!`
      });
    }
  }
}

// Milestone de streak
if (diasTreinoSemana >= 5) {
  milestones.push({
    tipo: 'streak',
    valor: diasTreinoSemana,
    key: `milestone:streak:${u.id}:${diasTreinoSemana}`,
    descricao: `${diasTreinoSemana} dias treinando essa semana!`
  });
}

if (milestones.length === 0) {
  return []; // Nenhum milestone — para o fluxo
}

return milestones.map(m => ({
  ...u,
  milestone: m
}));

